"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[685],{1296:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"defaultSidebar":[{"type":"link","href":"/SaveInstance420Edition/docs/intro","label":"Make your first save","docId":"intro","unlisted":false},{"type":"link","href":"/SaveInstance420Edition/docs/streaming","label":"Load streamed regions","docId":"streaming","unlisted":false},{"type":"link","href":"/SaveInstance420Edition/docs/decompilation","label":"Decompile scripts","docId":"decompilation","unlisted":false},{"type":"link","href":"/SaveInstance420Edition/docs/options","label":"Options reference","docId":"options","unlisted":false},{"type":"link","href":"/SaveInstance420Edition/docs/troubleshooting","label":"Troubleshoot an export","docId":"troubleshooting","unlisted":false},{"type":"link","href":"/SaveInstance420Edition/docs/privacy","label":"Run statistics and privacy","docId":"privacy","unlisted":false},{"type":"link","href":"/SaveInstance420Edition/docs/development","label":"Develop SaveInstance","docId":"development","unlisted":false}]},"docs":{"decompilation":{"id":"decompilation","title":"Decompile scripts","description":"The client never receives Roblox source code, only compiled bytecode for the scripts it runs. SaveInstance turns that bytecode back into readable Luau with a decompiler and writes it into each script\'s Source.","sidebar":"defaultSidebar"},"development":{"id":"development","title":"Develop SaveInstance","description":"saveinstance.luau at the repository root is generated. Edit the modules in src/ and rebuild.","sidebar":"defaultSidebar"},"intro":{"id":"intro","title":"Make your first save","description":"1. Load and run","sidebar":"defaultSidebar"},"options":{"id":"options","title":"Options reference","description":"Pass options as a table: saveinstance({ Decompile = false }). Names are case-insensitive. An unknown name prints a warning and is ignored.","sidebar":"defaultSidebar"},"privacy":{"id":"privacy","title":"Run statistics and privacy","description":"SaveInstance 420 Edition tracks execution data (run statistics) for robloxscripts.com. When the script loads, it starts robloxscripts.com\'s Script Ops reporter. The maintainer uses these numbers to see how many people run SaveInstance, on which executors, and whether saves work.","sidebar":"defaultSidebar"},"streaming":{"id":"streaming","title":"Load streamed regions","description":"In a game with StreamingEnabled, the server only sends your client the area around your character. A save of that client state misses everything farther away.","sidebar":"defaultSidebar"},"troubleshooting":{"id":"troubleshooting","title":"Troubleshoot an export","description":"Run the failing save again with Debug = true and keep SaveInstance420/debug .log from your executor\'s workspace. Change one option at a time.","sidebar":"defaultSidebar"}}}}')}}]);